/// Explicit reason a straight skeleton was not materialized.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum StraightSkeletonBlocker2 {
    /// The contour contains a non-line segment.
    UnsupportedSegment { segment_index: usize },
    /// A top-level curve family has no native exact wavefront implementation.
    UnsupportedCurveFamily {
        curve_index: usize,
        family: CurveFamily2,
    },
    /// Exact reduction of a conditionally supported family was indeterminate.
    UncertainCurveFamilyReduction {
        curve_index: usize,
        family: CurveFamily2,
    },
    /// The source contour has a self-contact or self-intersection.
    SelfContact,
    /// Source self-contact classification was indeterminate.
    UncertainSelfContact,
    /// Exact signed area was unavailable.
    UnsupportedSignedArea,
    /// The contour has zero signed area.
    DegenerateSignedArea,
    /// Signed-area orientation could not be decided.
    UncertainOrientation,
    /// Multiple topological event classes share one exact time.
    DegenerateSimultaneousEvents,
    /// A certified split did not yield two valid wavefront cycles.
    InvalidSplitTopology,
    /// A source vertex is collinear or otherwise locally degenerate.
    DegenerateVertex { vertex_index: usize },
    /// A local turn could not be classified exactly.
    UncertainVertexTurn { vertex_index: usize },
    /// Two active wavefront supports became parallel before terminal collapse.
    ParallelWavefrontSupports {
        first_source_edge: usize,
        second_source_edge: usize,
    },
    /// A wavefront relation could not be decided exactly.
    UncertainWavefrontRelation,
    /// Candidate collapse times could not be totally ordered.
    UncertainEventOrdering,
    /// The active wavefront had no future edge event.
    MissingFutureEvent,
    /// An event failed to advance beyond the current wavefront time.
    NonAdvancingEvent,
    /// A circular support reached zero radius before the next local vanish event.
    CircularRadiusCollapseRequired { source_edge: usize },
    /// Two curved supports survived and require a dedicated terminal transition.
    CurvedTerminalPairRequired {
        first_source_edge: usize,
        second_source_edge: usize,
    },
}

/// Kind and source evidence retained by one skeleton node.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum StraightSkeletonNodeKind2 {
    /// Source polygon vertex at wavefront time zero.
    SourceVertex { source_vertex: usize },
    /// One or more source-edge collapse events at the same point and time.
    EdgeEvent { collapsed_source_edges: Vec<usize> },
    /// A shrinking circular edge closed into a detached full circle.
    BubbleEvent { source_edge: usize },
    /// A reflex vertex was replaced by a generated expanding semicircle.
    SpliceEvent {
        source_vertex: usize,
        left_source_edge: usize,
        right_source_edge: usize,
    },
    /// A reflex vertex incident to event-generated geometry was replaced by
    /// an expanding semicircular support.
    SupportSpliceEvent {
        left: StraightSkeletonSupportProvenance2,
        right: StraightSkeletonSupportProvenance2,
    },
    /// Several independently applicable event transitions share one exact
    /// space-time graph node.
    EventCluster {
        events: Vec<StraightSkeletonNodeKind2>,
    },
    /// One or more wavefront supports collapsed after event-generated geometry
    /// entered the active cycle.
    SupportEvent {
        collapsed_supports: Vec<StraightSkeletonSupportProvenance2>,
    },
    /// Two nonadjacent finite wavefront edges touched in their interiors.
    SqueezeEvent {
        first: StraightSkeletonSupportProvenance2,
        second: StraightSkeletonSupportProvenance2,
    },
    /// A reflex vertex contacted the live interior of a nonincident edge.
    SplitEvent {
        left_source_edge: usize,
        right_source_edge: usize,
        hit_source_edge: usize,
    },
    /// A reflex vertex contacted a nonincident edge after generated geometry
    /// entered at least one side of the event.
    SupportSplitEvent {
        left: StraightSkeletonSupportProvenance2,
        right: StraightSkeletonSupportProvenance2,
        hit: StraightSkeletonSupportProvenance2,
    },
    /// Several wavefront vertices met at one non-general-position event.
    VertexEvent {
        incident_source_edges: Vec<usize>,
        collapsed_source_edges: Vec<usize>,
    },
}

/// Provenance of a source or event-generated wavefront support.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum StraightSkeletonSupportProvenance2 {
    /// Support translated from one authored contour edge.
    SourceEdge { source_edge: usize },
    /// Expanding semicircular support inserted by a splice event.
    SpliceArc {
        splice_node: usize,
        left_source_edge: usize,
        right_source_edge: usize,
    },
    /// Expanding semicircular support inserted when at least one incident
    /// support was itself generated by an earlier event.
    SupportSpliceArc {
        splice_node: usize,
        left: Box<StraightSkeletonSupportProvenance2>,
        right: Box<StraightSkeletonSupportProvenance2>,
    },
}

/// Exact straight-skeleton graph node.
#[derive(Clone, Debug, PartialEq)]
pub struct StraightSkeletonNode2 {
    point: Point2,
    time: Real,
    kind: StraightSkeletonNodeKind2,
}

impl StraightSkeletonNode2 {
    /// Return the exact node point.
    pub const fn point(&self) -> &Point2 {
        &self.point
    }

    /// Return the exact inward wavefront time.
    pub const fn time(&self) -> &Real {
        &self.time
    }

    /// Return source/event evidence for this node.
    pub const fn kind(&self) -> &StraightSkeletonNodeKind2 {
        &self.kind
    }
}

fn collapsed_support_provenance(
    kind: &StraightSkeletonNodeKind2,
) -> Option<Vec<StraightSkeletonSupportProvenance2>> {
    match kind {
        StraightSkeletonNodeKind2::EdgeEvent {
            collapsed_source_edges,
        } => Some(
            collapsed_source_edges
                .iter()
                .copied()
                .map(|source_edge| StraightSkeletonSupportProvenance2::SourceEdge { source_edge })
                .collect(),
        ),
        StraightSkeletonNodeKind2::SupportEvent { collapsed_supports } => {
            Some(collapsed_supports.clone())
        }
        _ => None,
    }
}

fn collapsed_support_node_kind(
    mut provenances: Vec<StraightSkeletonSupportProvenance2>,
) -> StraightSkeletonNodeKind2 {
    let mut deduplicated = Vec::with_capacity(provenances.len());
    for provenance in provenances.drain(..) {
        if !deduplicated.contains(&provenance) {
            deduplicated.push(provenance);
        }
    }
    let mut source_edges = deduplicated
        .iter()
        .filter_map(|provenance| match provenance {
            StraightSkeletonSupportProvenance2::SourceEdge { source_edge } => Some(*source_edge),
            _ => None,
        })
        .collect::<Vec<_>>();
    if source_edges.len() == deduplicated.len() {
        source_edges.sort_unstable();
        source_edges.dedup();
        StraightSkeletonNodeKind2::EdgeEvent {
            collapsed_source_edges: source_edges,
        }
    } else {
        StraightSkeletonNodeKind2::SupportEvent {
            collapsed_supports: deduplicated,
        }
    }
}

fn append_cluster_node_kind(
    events: &mut Vec<StraightSkeletonNodeKind2>,
    kind: StraightSkeletonNodeKind2,
) {
    if let StraightSkeletonNodeKind2::EventCluster { events: nested } = kind {
        for nested in nested {
            append_cluster_node_kind(events, nested);
        }
        return;
    }
    if let Some(mut collapsed) = collapsed_support_provenance(&kind)
        && let Some(index) = events
            .iter()
            .position(|event| collapsed_support_provenance(event).is_some())
    {
        collapsed.extend(collapsed_support_provenance(&events[index]).unwrap());
        events[index] = collapsed_support_node_kind(collapsed);
        return;
    }
    if !events.contains(&kind) {
        events.push(kind);
    }
}

fn merge_straight_skeleton_node_kind(
    existing: &mut StraightSkeletonNodeKind2,
    added: StraightSkeletonNodeKind2,
) -> Result<(), StraightSkeletonBlocker2> {
    if existing == &added {
        return Ok(());
    }
    if matches!(existing, StraightSkeletonNodeKind2::SourceVertex { .. })
        || matches!(&added, StraightSkeletonNodeKind2::SourceVertex { .. })
    {
        return Err(StraightSkeletonBlocker2::InvalidSplitTopology);
    }
    let original = std::mem::replace(
        existing,
        StraightSkeletonNodeKind2::EventCluster { events: Vec::new() },
    );
    let mut events = Vec::new();
    append_cluster_node_kind(&mut events, original);
    append_cluster_node_kind(&mut events, added);
    *existing = match events.as_slice() {
        [only] => only.clone(),
        _ => StraightSkeletonNodeKind2::EventCluster { events },
    };
    Ok(())
}

fn node_kind_contains_squeeze(kind: &StraightSkeletonNodeKind2) -> bool {
    match kind {
        StraightSkeletonNodeKind2::SqueezeEvent { .. } => true,
        StraightSkeletonNodeKind2::EventCluster { events } => {
            events.iter().any(node_kind_contains_squeeze)
        }
        _ => false,
    }
}

fn node_kind_contains_source_collapse(
    kind: &StraightSkeletonNodeKind2,
    source_edge: usize,
) -> bool {
    match kind {
        StraightSkeletonNodeKind2::EdgeEvent {
            collapsed_source_edges,
        } => collapsed_source_edges.contains(&source_edge),
        StraightSkeletonNodeKind2::SupportEvent { collapsed_supports } => collapsed_supports
            .contains(&StraightSkeletonSupportProvenance2::SourceEdge { source_edge }),
        StraightSkeletonNodeKind2::EventCluster { events } => events
            .iter()
            .any(|event| node_kind_contains_source_collapse(event, source_edge)),
        _ => false,
    }
}

fn replace_source_collapse_with_bubble(
    kind: &mut StraightSkeletonNodeKind2,
    source_edge: usize,
) -> bool {
    let original = std::mem::replace(
        kind,
        StraightSkeletonNodeKind2::EventCluster { events: Vec::new() },
    );
    let mut events = Vec::new();
    append_cluster_node_kind(&mut events, original);
    let Some(index) = events.iter().position(|event| {
        collapsed_support_provenance(event).is_some_and(|provenances| {
            provenances.contains(&StraightSkeletonSupportProvenance2::SourceEdge { source_edge })
        })
    }) else {
        *kind = match events.as_slice() {
            [only] => only.clone(),
            _ => StraightSkeletonNodeKind2::EventCluster { events },
        };
        return false;
    };
    let mut collapsed = collapsed_support_provenance(&events.remove(index)).unwrap();
    collapsed.retain(|provenance| {
        provenance != &StraightSkeletonSupportProvenance2::SourceEdge { source_edge }
    });
    if !collapsed.is_empty() {
        append_cluster_node_kind(&mut events, collapsed_support_node_kind(collapsed));
    }
    append_cluster_node_kind(
        &mut events,
        StraightSkeletonNodeKind2::BubbleEvent { source_edge },
    );
    *kind = match events.as_slice() {
        [only] => only.clone(),
        _ => StraightSkeletonNodeKind2::EventCluster { events },
    };
    true
}

fn recorded_shape_preserving_event_node(
    nodes: &mut Vec<StraightSkeletonNode2>,
    point: Point2,
    time: Real,
    kind: StraightSkeletonNodeKind2,
) -> Result<usize, StraightSkeletonBlocker2> {
    if let Some(index) = nodes
        .iter()
        .position(|node| node.point == point && node.time == time)
    {
        merge_straight_skeleton_node_kind(&mut nodes[index].kind, kind)?;
        return Ok(index);
    }
    let index = nodes.len();
    nodes.push(StraightSkeletonNode2 { point, time, kind });
    Ok(index)
}

